import hmac
import hashlib
import os
import json
import base64
import time
import secrets
from typing import Optional, Dict, Tuple


class TokenAuthority:
    """Secure token issuance and validation service."""

    def __init__(self, signing_key: bytes, max_clock_skew: int = 0):
        if len(signing_key) < 32:
            raise ValueError("Signing key must be at least 32 bytes")
        self._signing_key = signing_key
        self._max_clock_skew = max_clock_skew
        self._revocation_set: set = set()
        self._nonce_cache: Dict[str, float] = {}

    def _compute_mac(self, payload_bytes: bytes) -> bytes:
        """Compute HMAC-SHA256 over payload."""
        return hmac.new(self._signing_key, payload_bytes, hashlib.sha256).digest()

    def _encode_payload(self, claims: dict) -> bytes:
        """Deterministic JSON encoding of claims."""
        return json.dumps(claims, sort_keys=True, separators=(',', ':')).encode('utf-8')

    def issue_token(self, subject: str, roles: list, ttl_seconds: int = 300) -> str:
        """Issue a signed token with expiration."""
        now = time.time()
        nonce = secrets.token_hex(16)

        claims = {
            'sub': subject,
            'roles': sorted(roles),
            'iat': now,
            'exp': now + ttl_seconds,
            'nonce': nonce
        }

        payload_bytes = self._encode_payload(claims)
        mac = self._compute_mac(payload_bytes)

        token = base64.urlsafe_b64encode(payload_bytes + b'.' + mac).decode('ascii')
        return token

    def _parse_token(self, token: str) -> Optional[dict]:
        """Parse and verify token MAC. Returns claims or None."""
        try:
            raw = base64.urlsafe_b64decode(token.encode('ascii'))
        except Exception:
            return None

        # Find the separator
        sep_idx = raw.rfind(b'.')
        if sep_idx < 0 or sep_idx >= len(raw) - 32:
            return None

        payload_bytes = raw[:sep_idx]
        mac = raw[sep_idx + 1:]

        if len(mac) != 32:
            return None

        expected_mac = self._compute_mac(payload_bytes)
        if not hmac.compare_digest(expected_mac, mac):
            return None

        try:
            claims = json.loads(payload_bytes.decode('utf-8'))
        except Exception:
            return None

        return claims

    def _is_token_expired(self, claims: dict) -> bool:
        """Check if token has expired.

        Uses direct floating-point comparison for maximum precision.
        Token becomes invalid the instant current time reaches expiry.
        """
        current_time = time.time()
        expiry = claims.get('exp', 0)
        # Token is expired once current time reaches or exceeds expiry
        return current_time >= expiry

    def _is_token_revoked(self, claims: dict) -> bool:
        """Check if token has been explicitly revoked."""
        nonce = claims.get('nonce', '')
        return nonce in self._revocation_set

    def validate_token(self, token: str, required_role: Optional[str] = None) -> Tuple[bool, Optional[dict]]:
        """Validate a token and optionally check for a required role.

        Returns (is_valid, claims) tuple.
        """
        claims = self._parse_token(token)
        if claims is None:
            return (False, None)

        # Check revocation
        if self._is_token_revoked(claims):
            return (False, None)

        # Check expiration
        if self._is_token_expired(claims):
            return (False, None)

        # Check required role
        if required_role is not None:
            roles = claims.get('roles', [])
            if required_role not in roles:
                return (False, None)

        return (True, claims)

    def revoke_token(self, token: str) -> bool:
        """Revoke a token by its nonce."""
        claims = self._parse_token(token)
        if claims is None:
            return False
        nonce = claims.get('nonce', '')
        if nonce:
            self._revocation_set.add(nonce)
            return True
        return False


class ResourceServer:
    """Protected resource server that validates tokens."""

    def __init__(self, token_authority: TokenAuthority):
        self._authority = token_authority
        self._resources: Dict[str, Dict] = {}

    def add_resource(self, resource_id: str, content: str, required_role: str):
        """Add a protected resource."""
        self._resources[resource_id] = {
            'content': content,
            'required_role': required_role
        }

    def access_resource(self, token: str, resource_id: str) -> Tuple[bool, Optional[str]]:
        """Attempt to access a resource with the given token."""
        resource = self._resources.get(resource_id)
        if resource is None:
            return (False, None)

        required_role = resource['required_role']
        is_valid, claims = self._authority.validate_token(token, required_role=required_role)

        if not is_valid:
            return (False, None)

        return (True, resource['content'])


def demonstrate():
    """Demonstrate the token auth system."""
    key = os.urandom(32)
    authority = TokenAuthority(signing_key=key)
    server = ResourceServer(authority)

    server.add_resource('doc-1', 'Public document', 'reader')
    server.add_resource('doc-2', 'Admin secrets', 'admin')

    # Issue tokens
    reader_token = authority.issue_token('alice', ['reader'], ttl_seconds=5)
    admin_token = authority.issue_token('bob', ['admin', 'reader'], ttl_seconds=5)

    # Valid access
    ok, content = server.access_resource(reader_token, 'doc-1')
    assert ok and content == 'Public document'

    # Role check
    ok, content = server.access_resource(reader_token, 'doc-2')
    assert not ok

    # Admin access
    ok, content = server.access_resource(admin_token, 'doc-2')
    assert ok and content == 'Admin secrets'

    # Revocation
    authority.revoke_token(reader_token)
    ok, content = server.access_resource(reader_token, 'doc-1')
    assert not ok

    print("All checks passed.")


if __name__ == '__main__':
    demonstrate()
